select *
from (

) t
order by t.publish_time desc, t.notice_id desc

select count(1)
from (

) t
where t.read_status = '0'

select count(1) from ( select notice_id, convert('system' using utf8mb4) collate utf8mb4_general_ci as notice_source from sys_notice where status = '0'
union all
select cn.notice_id, convert('club' using utf8mb4) collate utf8mb4_general_ci as notice_source from club_notice cn where cn.status = '1' and cn.del_flag = '0' and exists ( select 1 from club_member cm where cm.club_id = cn.club_id and cm.user_id = #{userId} and cm.status = '0' and cm.del_flag = '0' ) ) t where t.notice_source = #{noticeSource} and t.notice_id = #{noticeId}
